# typed: true
# frozen_string_literal: true

module TwoFactorRequirement
  module Queries
    PRESTO_QUERY_RESULTS_LIMIT = 1_000_000

    class Base
      def reason
        TwoFactorRequirement::Reason.from_symbol(self.class.name&.demodulize.underscore.to_sym)
      end

      # if true, the discovery job will use the query to continuously discover users required for 2FA
      # if false, the discovery job will exclude it
      def steady_state_enabled?
        false
      end

      def run_business_admin_query(yielded_batch_size:, affected_user_threshold: nil, &block)
        query_start_time = Time.now.utc

        business_admin_query = build_business_admin_query(affected_user_threshold: affected_user_threshold)
        _, business_results = GitHub.presto.run(business_admin_query)

        org_admin_query = build_org_admin_query(affected_user_threshold: affected_user_threshold)
        _, org_results = GitHub.presto.run(org_admin_query)

        time_elapsed = GitHub::Dogstats.duration(query_start_time, Time.now.utc)
        results = business_results + org_results

        GitHub.dogstats.increment("two_factor_requirement_discovery.admin_query_count", tags: ["reason:#{reason}"])
        GitHub.dogstats.distribution("two_factor_requirement_discovery.admin_query_duration", time_elapsed, tags: ["reason:#{reason}"])
        results.each_slice(yielded_batch_size).each do |id_slice|
          block.call(id_slice, reason)
        end
        results.length
      end

      def run_query(yielded_batch_size:, lookback: nil, limit: nil, additional_user_filter: nil, &block)
        limit = PRESTO_QUERY_RESULTS_LIMIT if !limit || limit > PRESTO_QUERY_RESULTS_LIMIT
        query = build_query(lookback: lookback, limit: limit, additional_user_filter: additional_user_filter)
        query_start_time = Time.now.utc
        _, results = GitHub.presto.run(query)
        time_elapsed = GitHub::Dogstats.duration(query_start_time, Time.now.utc)
        GitHub.dogstats.increment("two_factor_requirement_discovery.query_count", tags: ["reason:#{reason}"])
        GitHub.dogstats.distribution("two_factor_requirement_discovery.query_duration", time_elapsed, tags: ["reason:#{reason}"])

        results.flatten.each_slice(yielded_batch_size).each do |results_batch|
          block.call(results_batch, reason)
        end
        results.flatten.length
      end

      # The specific query that must be implemented on each QueryBuilder::Base subclass.
      #
      # lookback_timestamp - A timestamp string for limiting discovery queries. If falsey, no date limitation should be applied.
      #
      # Returns a query string that is nested (see self.build_query) which includes a `filered_users` CTE and an optional limit.
      def select_statement(lookback_timestamp: nil)
        raise NotImplementedError, "#{self.class} needs to implement `self.select_statement`"
      end

