      def cohort_ctes(lookback_timestamp: nil)
        # query method implemented by the TwoFactorRequirement::Queries subclasses
        #
        # optional method for cohort queries that need additional CTEs, nessesary to ensure that both the enrollment
        # transition and admin mailer transition can run successfully.
        #
        # defining here to appease sorbet
      end

      # Builds the full query for selecting users required for 2FA for the specific reason.
      #
      # lookback - The `Time` used for limiting discovery queries.
      # limit - Limit the returned user IDs by an integer value. (optional integer)
      # additional_user_filter - A symbol (:two_factor_enabled or :two_factor_disabled) used for limiting the underlying query further. Optional.
      #
      # Wraps the specific select statement with a CTE for filtered_users and applies a limit (if supplied).
      def build_query(lookback: nil, limit: nil, additional_user_filter: nil)
        lookback_timestamp = lookback&.to_formatted_s(:db)
        %Q(
          #{self.filtered_users_cte(additional_user_filter: additional_user_filter)}
          #{self.cohort_ctes(lookback_timestamp: lookback_timestamp) if self.respond_to?(:cohort_ctes)}
          #{self.select_statement(lookback_timestamp: lookback_timestamp)}
          #{self.limit_query_string(limit)}
        )
      end

      # Builds the full query for selecting admins of orgs and enterprises
      # whos users are required for 2FA for the specific reason.
      #
      # affected_user_threshold - Admins will be notified if the number of affected users is greater than or equal to this threshold.
      #
      # Wraps the specific select statement as a CTE (common table expression) to be used in queries to find
      # the corresponding admins.
      def build_org_admin_query(affected_user_threshold: 50)
        %Q(
          #{self.filtered_users_cte(filter_emus: true, requirement_reason_to_include: reason)}
          #{self.respond_to?(:cohort_ctes) ? self.cohort_ctes : ""}
          , cohort_users as (
            #{self.select_statement}
          ),
          orgs AS (
            SELECT
              OU.id,
              OU.login,
              Count(distinct A.actor_id) AS user_count,
              Sum(IF(T.id IS NULL, 0, 1)) AS user_2fa_enabled_count
            FROM
              #{self.abilities_table} A
              INNER JOIN cohort_users CU ON CU.id = A.actor_id AND A.actor_type = 'User'
              INNER JOIN #{self.users_table} OU ON OU.id = A.subject_id AND OU.type = 'Organization'
              LEFT JOIN #{self.two_factor_credentials_table} T on T.user_id = CU.id
            WHERE
              A.subject_type = 'Organization'
              AND OU.PLAN IS NOT NULL
              AND OU.PLAN <> 'free'
            GROUP BY
              OU.id,
              OU.login
          ),
          org_admins AS (
            SELECT
              DISTINCT A.actor_id AS id,
              O.id AS org_id
            FROM
              #{self.abilities_table} A
              INNER JOIN orgs O ON O.id = A.subject_id
              AND A.subject_type = 'Organization'
            WHERE
              A.actor_type = 'User'
              AND A.action = 2
          )
          SELECT
            OA.id AS admin_user_id,
            O.id AS entity_id,
            O.login AS entity_name,
            1 AS is_org,
            O.user_count,
            O.user_2fa_enabled_count
          FROM
            org_admins OA
            INNER JOIN orgs O ON O.id = OA.org_id
            LEFT JOIN #{self.business_organization_memberships_table} BOM ON BOM.organization_id = O.id
          WHERE
            BOM.id IS NULL
            AND user_count >= #{affected_user_threshold}
            AND user_2fa_enabled_count != user_count
        )
      end

      def build_business_admin_query(affected_user_threshold: 50)
        %Q(
          #{self.filtered_users_cte(filter_emus: true, requirement_reason_to_include: reason)}
          #{self.respond_to?(:cohort_ctes) ? self.cohort_ctes : ""}
          , cohort_users as (
            #{self.select_statement}
          ),
          orgs AS (
            SELECT
              OU.id,
              OU.login,
              Count(distinct A.actor_id) AS user_count,
              Sum(IF(T.id IS NULL, 0, 1)) AS user_2fa_enabled_count
            FROM
              #{self.abilities_table} A
              INNER JOIN cohort_users CU ON CU.id = A.actor_id AND A.actor_type = 'User'
              INNER JOIN #{self.users_table} OU ON OU.id = A.subject_id AND OU.type = 'Organization'
              LEFT JOIN #{self.two_factor_credentials_table} T on T.user_id = CU.id
            WHERE
              A.subject_type = 'Organization'
              AND OU.PLAN IS NOT NULL
              AND OU.PLAN <> 'free'
            GROUP BY
              OU.id,
              OU.login
          ),
          businesses AS (
            SELECT
              S.id,
              S.slug,
              Count(distinct S.actor_id) AS user_count,
              Sum(IF(T.id IS NULL, 0, 1)) AS user_2fa_enabled_count
            FROM
              (
                SELECT
                  A.subject_id AS id,
                  B.slug,
                  A.actor_id
                FROM
                  #{self.abilities_table} A
                  INNER JOIN cohort_users CU ON CU.id = A.actor_id AND A.actor_type = 'User'
                  INNER JOIN #{self.businesses_table} B ON B.id = A.subject_id
                WHERE
                  A.subject_type = 'Business'
                  AND B.deleted_at IS NULL
                UNION ALL
                SELECT
                  BOM.business_id AS id,
                  B.slug,
                  A.actor_id
                FROM
                  orgs O
                  INNER JOIN #{self.business_organization_memberships_table} BOM ON BOM.organization_id = O.id
                  INNER JOIN #{self.abilities_table} A ON A.subject_id = O.id AND A.subject_type = 'Organization'
                  INNER JOIN cohort_users CU ON CU.id = A.actor_id
                  INNER JOIN #{self.businesses_table} B ON B.id = BOM.business_id
                WHERE
                  A.actor_type = 'User'
                  AND B.deleted_at IS NULL
              ) S
              LEFT JOIN #{self.two_factor_credentials_table} T on T.user_id = S.actor_id
            GROUP BY
              S.id,
              S.slug
          ),
          business_admins AS (
            SELECT
              DISTINCT A.actor_id AS id,
              B.id AS business_id
            FROM
              #{self.abilities_table} A
              INNER JOIN businesses B ON B.id = A.subject_id AND A.subject_type = 'Business'
            WHERE
              A.actor_type = 'User'
              AND A.action = 2
          )
          SELECT
            BA.id AS admin_user_id,
            B.id AS entity_id,
            B.slug AS entity_name,
            0 AS is_org,
            B.user_count,
            B.user_2fa_enabled_count
          FROM
            business_admins BA
            INNER JOIN businesses B ON B.id = BA.business_id
          WHERE
            B.user_count >= #{affected_user_threshold}
            AND B.user_2fa_enabled_count != B.user_count
        )
      end

      private

      # Requires users that are in an optional 2FA requirement state (e.g. never flagged) and is not an EMU user
      # If additional_user_filter is provided, the filter may also filter out 2FA enabled or disabled users.
      #
      # additional_user_filter - Symbol (nil, :two_factor_enabled, or :two_factor_disabled)
      # filter_emus - Boolean (default false). If true, EMU users will be filtered out.
      # requirement_reason_to_include -  TwoFactorRequirement::Reason (default nil). If defined, this will include
      # users that are already enrolled for the specified reason. Use case: the admin query should include users
      # that have already been enrolled.
      def filtered_users_cte(additional_user_filter: nil, filter_emus: false, requirement_reason_to_include: nil)
        join = "LEFT JOIN #{self.two_factor_credentials_table} FUTFC on FUTFC.user_id = u.id" if additional_user_filter
        join_where_condition = case additional_user_filter
        when :two_factor_enabled
          "AND FUTFC.id IS NOT NULL"
        when :two_factor_disabled
          "AND FUTFC.id IS NULL"
        else
          ""
        end

        special_case_underscores = User::EnterpriseManagedDependency::INVALID_UNDERSCORE_LOGIN.map { |login| "'#{login}'" }.join(", ")
        filter_emu_condition = filter_emus ? "AND (NOT REGEXP_LIKE(u.login, '[A-z0-9]+_[A-z0-9]+') OR u.login IN (#{special_case_underscores}))" : ""
        metadata_join = "LEFT JOIN #{self.two_factor_requirement_metadata_table} m on m.user_id = u.id"
        user_condition = requirement_reason_to_include.blank? ? "AND (m.id IS NULL OR m.state = 0)" : "AND (m.id IS NULL OR m.state = 0 or m.requirement_reason = #{requirement_reason_to_include.to_value})"
        # temporarily filter out some Intel service accounts, that are unprepared for 2FA https://github.com/github/authentication/issues/3034
        intel_exclusion = GitHub.flipper[:bulwark_intel_exemption].enabled?
        intel_exclusion_cte = if intel_exclusion
          "intel_exclusions AS (
            SELECT actor_id as id
            FROM   #{self.abilities_table} ab
            WHERE  ab.actor_type   = 'User'
            AND    ab.subject_id   = (SELECT id FROM #{self.teams_table}
              WHERE organization_id = (SELECT id FROM #{self.users_table}
                WHERE login = 'intel-innersource' AND type = 'Organization')
              AND slug = 'all-bb-generic-accounts')
            AND    ab.subject_type = 'Team'
            AND    ab.priority     = 1
          ),"
        else
          ""
        end
        intel_exclusion_join = intel_exclusion ? "LEFT JOIN intel_exclusions ie on ie.id = u.id" : ""
        intel_exclusion_null_check = intel_exclusion ? "AND     ie.id IS NULL" : ""

        %Q(
          WITH student_coupons as (
            SELECT  id
            FROM    #{self.coupons_table}
            WHERE   code LIKE '%student%'
          ),
          students as (
            SELECT distinct cr.user_id as id
            FROM #{self.coupon_redemptions_table} cr
            INNER JOIN student_coupons c ON c.id = cr.coupon_id
            WHERE cr.expired = false
            OR cr.expires_at > date_add('year', -1, now())
          ),
          #{intel_exclusion_cte}
          filtered_users AS (
              SELECT  u.id
              FROM    #{self.users_table} u
              LEFT JOIN students s on s.id = u.id
              #{intel_exclusion_join}
              #{metadata_join}
              #{join}
              WHERE   u."type" = 'User'
              #{user_condition}
              AND     s.id IS NULL
              #{intel_exclusion_null_check}
              #{filter_emu_condition}
              #{join_where_condition}
          )
        )
      end

      def limit_query_string(limit)
        raise ArgumentError, "limit must be a number > 0" if !limit.nil? && (!limit.is_a?(Integer) || limit < 1)
        return "LIMIT #{limit}" if limit
        ""
      end

